import{z as l,x as n,o as t,c as d,q as o,j as s,D as r,d as a,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"性能开销","description":"","frontmatter":{"title":"性能开销","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-performance-overhead.md","filePath":"cs/virt-performance-overhead.md","lastUpdated":1791413859000}'),c={name:"cs/virt-performance-overhead.md"};function D(p,E,m,h,T,f){const B=n("Mermaid");return t(),d("div",null,[E[2]||(E[2]=o('<h1 id="性能开销" tabindex="-1">性能开销 <a class="header-anchor" href="#性能开销" aria-label="Permalink to &quot;性能开销&quot;">​</a></h1><div class="epigraph"><p>虚拟化没有单一的「开销百分比」：税按路径征收。负载骑在哪条路上——译址、中断、网络、块——哪条路上的固定成本就被乘上吞吐。</p><footer>—— 据 KVM/QEMU 与主流云厂商公开性能文档的方法论整理</footer></div><p><a href="/cs/virt-security-boundary">上一课</a>说隔离强度等于 TCB 的正确性；这一课说它的价格。主干课已拆过各项机制的原理：<a href="/cs/shadow-page-table">影子页表与 EPT</a>、<a href="/cs/interrupt-virtualization">posted interrupt</a>、<a href="/cs/clock-virtualization">时钟虚拟化</a>、<a href="/cs/virtio">virtio</a>。本课不再复述机制，只做两件事：把税按路径归账，以及给出测得准的方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPU 路径几乎已免税：硬件辅助把敏感指令的陷入做成微架构级，纯计算负载在虚机里损失常在个位数百分比；容器不引入任何陷入，这条路径税为零。真正的账在别处。<strong>译址</strong>：EPT 让一次访存的地址翻译变成两层查表，TLB 未中时页表遍历深度翻倍，大页因此在虚机里比裸机更值钱——这是内存密集负载的主要税目。<strong>I/O</strong>：网络沿<a href="/cs/virt-network-virtualization">上一课的软件路径</a>按包计费，virtio 后端每笔 I/O 加一次唤醒；块设备同理，<a href="/cs/blk-mq">多队列块层</a>之上再垫一层虚拟队列。<strong>双份页缓存</strong>：客机把文件页缓存一遍，宿主又把整个磁盘镜像当文件缓存一遍（页的分类见<a href="/cs/anon-vs-file-page">匿名页对文件页</a>），同一份数据占两份内存——这是容器密度优于虚机的隐蔽大头。<strong>时间</strong>：虚拟时钟源的偏差让虚机里的计时器既可能走快也可能走慢，<a href="/cs/clock-virtualization">时钟虚拟化</a>的欠账会直接污染你的测量。</p><p><span class="marginnote">数字实例：裸机一次 TLB 未中最深走 4 层页表；开 EPT 后客虚址先到客物理再到宿物理，一次未中最深要走 8 层。TLB 命中率高的负载几乎无感，访存随机、工作集大的负载这一项就是主税目——这也是大页在虚机里更值钱的算术来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法与归账同样重要：税表有了，还得有一套不让我们自己骗自己的测量纪律。</p><h3 id="测量的纪律" tabindex="-1">测量的纪律 <a class="header-anchor" href="#测量的纪律" aria-label="Permalink to &quot;测量的纪律&quot;">​</a></h3><p>微基准的说谎方式有三种。其一，只测空载开销：逃逸路径与后端线程闲着时是热的，有负载时缓存与 TLB 被客户工作集冲掉，空载数字全部失效。其二，把别的限制当成虚拟化税：上一课的 <code>cpu.max</code> 窗口烧完会让整组冻结，测出来像「虚机慢」，其实是配额；宿主 <a href="/cs/memcg">memcg</a> 挤压 QEMU 进程同理。其三，用客机时钟计客机时间：时钟源未校准时，结论建立在坏尺子上。可执行的纪律是：同一硬件 A/B、生产形态（真实设备集、真实内存量）、在 SLO 指标上读数、把宿主 <code>steal time</code> 与 cgroup 节流从税单里单列。</p><p><span class="marginnote">常见误区：测出「虚机比裸机慢三成」就归罪虚拟化。若宿主给虚机设了 cpu.max 窗口或 memcg 上限，尖峰时被冻住的那段时间是配额不是税；不把 cgroup 节流与 steal time 单列，归因就全错位了。</span></p>',11)),(t(),s(A,null,{default:r(()=>[i(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD%5B%22%E8%B4%9F%E8%BD%BD%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20CPU%5B%22%E8%AE%A1%E7%AE%97%E5%AF%86%E9%9B%86%3A%20%E8%BF%91%E5%8E%9F%E7%94%9F%22%5D%0A%20%20LOAD%20--%3E%20MEM%5B%22%E5%86%85%E5%AD%98%E5%AF%86%E9%9B%86%3A%20EPT%20%E7%BF%BB%E5%80%8D%E9%81%8D%E5%8E%86%22%5D%0A%20%20LOAD%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E5%AF%86%E9%9B%86%3A%20%E6%AF%8F%E5%8C%85%E8%BD%AF%E4%BB%B6%E8%B7%AF%E5%BE%84%22%5D%0A%20%20LOAD%20--%3E%20IO%5B%22I%2FO%20%E5%AF%86%E9%9B%86%3A%20%E8%99%9A%E6%8B%9F%E9%98%9F%E5%88%97%E5%8A%A0%E5%94%A4%E9%86%92%22%5D%0A%20%20LOAD%20--%3E%20FS%5B%22%E6%96%87%E4%BB%B6%E5%AF%86%E9%9B%86%3A%20%E5%8F%8C%E4%BB%BD%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20CPU%20--%3E%20VERDICT%5B%22%E6%8C%89%E8%B7%AF%E5%BE%84%E5%BD%92%E8%B4%A6%2C%20%E4%B8%8D%E7%BB%99%E6%80%BB%E5%88%86%22%5D%0A%20%20MEM%20--%3E%20VERDICT%0A%20%20NET%20--%3E%20VERDICT%0A%20%20IO%20--%3E%20VERDICT%0A%20%20FS%20--%3E%20VERDICT%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("把账算清后，课程里所有机制各就各位：半虚拟化与 vhost 买断的是 I/O 路径上的唤醒与往返（第二课的接缝判据）；直通与 DPDK 买断的是整个软件栈（第五课的旁路选项）；大页与 THP 买断的是译址层的遍历深度；气球与"),e("a",{href:"/cs/memory-balloon"},"内存超售"),a("则是在密度与稳定性之间记账。容器与虚机的差距由此可以精确表述："),e("strong",null,"容器免的是陷入税与双份缓存税，虚机免的是共享内核税"),a("。两边在同一负载上的差距，等于这两组税目在该负载路径上的和。没有全负或全零的一侧，只有路径上的逐项比较。")],-1)),(t(),s(A,null,{default:r(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD2%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E8%B4%9F%E8%BD%BD%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20VM%5B%22%E8%99%9A%E6%9C%BA%E7%A8%8E%E5%8D%95%22%5D%0A%20%20LOAD2%20--%3E%20CT%5B%22%E5%AE%B9%E5%99%A8%E7%A8%8E%E5%8D%95%22%5D%0A%20%20VM%20--%3E%20T1%5B%22%E4%BB%98%3A%20%E9%99%B7%E5%85%A5%E4%B8%8E%20EPT%20%E5%8F%8C%E5%B1%82%E9%81%8D%E5%8E%86%22%5D%0A%20%20VM%20--%3E%20T2%5B%22%E4%BB%98%3A%20%E5%8F%8C%E4%BB%BD%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20VM%20--%3E%20T3%5B%22%E5%85%8D%3A%20%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%E7%9A%84%E6%94%BB%E5%87%BB%E9%9D%A2%22%5D%0A%20%20CT%20--%3E%20T4%5B%22%E4%BB%98%3A%20%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%E7%A8%8E%22%5D%0A%20%20CT%20--%3E%20T5%5B%22%E5%85%8D%3A%20%E9%99%B7%E5%85%A5%E7%A8%8E%E4%B8%8E%E5%8F%8C%E7%BC%93%E5%AD%98%E7%A8%8E%22%5D%0A%20%20T1%20--%3E%20SUM%5B%22%E5%B7%AE%E8%B7%9D%20%3D%20%E8%AF%A5%E8%B7%AF%E5%BE%84%E4%B8%8A%E4%B8%A4%E7%BB%84%E7%A8%8E%E7%9B%AE%E4%B9%8B%E5%92%8C%22%5D%0A%20%20T2%20--%3E%20SUM%0A%20%20T4%20--%3E%20SUM%0A%20%20T5%20--%3E%20SUM%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p><span class="marginnote">steal time 可翻译成「被偷走的时间」：虚机想跑但物理核被调度给了别人的那一段。它不出现在任何用户态计时器里，只在内核统计里占一行——超售宿主上吞吐莫名下降，先看这一行再怪虚拟化。</span></p><p><span class="marginnote">一个必查项：虚机内核的 <code>steal time</code> 记录了「想跑没跑成」的时间。超售宿主上吞吐异常，先看 steal 再怪虚拟化——被偷走的份额不体现在任何用户态计时器里，只体现在这一行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「容器比虚机快百分之几」的普适数字——离开路径与负载，这种数字没有意义；也不展开 NUMA 与 vCPU 拓扑对齐（放错 NUMA 的税可能大于虚拟化本身，机制归调度课）。GPU 的开销结构已在上一课单独处理，嵌套虚拟化的加倍税归主干课。最后一个边界：测量的结论随内核版本过期——EPT、vhost、多队列都在演进，本课钉的是<strong>归账框架与纪律</strong>，数字请用当时硬件自测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>开销按路径征收：计算近原生，内存看 EPT 遍历，网络与块看每包每笔的软件路径。</li><li>双份页缓存是虚机密度劣势的隐蔽大头：客机缓存一遍，宿主再缓存镜像文件。</li><li>测量三戒：不测空载、不把配额当税、不用未校准的客机时钟。</li><li>容器免陷入与双缓存税，虚机免共享内核税；差距是路径上两组税目的和。</li><li>出处：据 KVM/QEMU 性能文档与云厂商公开测量方法论整理。</li></ul>',6))])}const g=l(c,[["render",D]]);export{C as __pageData,g as default};
